## Alpha Spectral Power Modeling
### Student's T Distribution Model

::: {.cell}
::: {.cell-output-display}
`````{=html}
<div data-pagedtable="false">
  <script data-pagedtable-source type="application/json">
{"columns":[{"label":["Term"],"name":[1],"type":["chr"],"align":["left"]},{"label":["X^2"],"name":[2],"type":["dbl"],"align":["right"]},{"label":["Df"],"name":[3],"type":["dbl"],"align":["right"]},{"label":["p"],"name":[4],"type":["chr"],"align":["left"]}],"data":[{"1":"pre_alpha","2":"5552.097","3":"1","4":"< .001"},{"1":"Group","2":"0.399","3":"1","4":"0.528"},{"1":"channel","2":"545.840","3":"2","4":"< .001"},{"1":"Group:channel","2":"9.006","3":"2","4":"0.011"}],"options":{"columns":{"min":{},"max":[10]},"rows":{"min":[10],"max":[10]},"pages":{}}}
  </script>
